package i18nspike

import "testing"

// TestGeneratedAccessors exercises the typed Go accessors generated by ts/gen.ts.
// A wrong argument type or a removed key is a compile error here.
func TestGeneratedAccessors(t *testing.T) {
	c, err := LoadCatalog(Locales)
	if err != nil {
		t.Fatal(err)
	}
	b, err := NewBundle(c)
	if err != nil {
		t.Fatal(err)
	}
	ja := b.Localizer("ja-JP")
	en := b.Localizer("en-US")
	tests := []struct{ got, want string }{
		{ja.DemoNotificationsUnread(3), "未読の通知が3件あります"},
		{en.DemoNotificationsUnread(1), "1 unread notification"},
		{ja.DemoFollowRank(2), "あなたは2番目のフォロワーです"},
		{en.DemoFollowRank(22), "You are the 22nd follower"},
		{en.DemoProfileFollowers(1234.5), "1,234.5 followers"},
		{en.DemoPostBoostedOwn("female", "Alice"), "Alice boosted her own post"},
		// ja has no translation: falls back to en.
		{ja.DemoProfileMoved("@alice@example.com", "Alice"), "Alice has moved to @alice@example.com."},
	}
	for _, tt := range tests {
		if tt.got != tt.want {
			t.Errorf("got %q, want %q", tt.got, tt.want)
		}
	}
}
